            anchor=d.newnode((xs-source['center'][0],y,zs-source['center'][1])); a,b=(anchor,clip) if side_index==0 else (clip,anchor); d.axial_member(a,b,source['EA_N']/16,tension/16,True,'fixture_rope',eid); d.fixed.update((anchor,q) for q in (1,2,3)); support.append(anchor)  # Preserve physical EA, initial tension and geometry; only independent remote-end translations are fixed.
