def cases():  # Return only the six concrete geometry/load/interpolation discriminators.
    return [('floor50_corrected_gravity_interp',lambda:floor_probe()),('floor50_corrected_force_interp',lambda:floor_probe(gravity=False)),('floor100_corrected_gravity_interp',lambda:floor_probe(large=True)),('floor100_corrected_force_interp',lambda:floor_probe(large=True,gravity=False)),('floor50_corrected_gravity_direct',lambda:floor_probe(direct=True)),('floor100_corrected_gravity_direct',lambda:floor_probe(large=True,direct=True))]  # Preserve failures rather than tuning a model until it passes.
